'use client';

import * as React from 'react';
import {createComponent, type EventName} from '@lit/react';
import '@material/web/labs/gb/components/slider/md-gb-slider.js';
import {SliderElement} from '@material/web/labs/gb/components/slider/slider-element.js';

/**
 * A Material Design slider component. Wraps <md-gb-slider>.
 * Docs: https://material-web.dev/3.0/components/slider/
 */
export const MdSlider = createComponent({
  react: React,
  tagName: 'md-gb-slider',
  elementClass: SliderElement,
  events: {
    onChange: 'change' as EventName<Event>,
    onInput: 'input' as EventName<InputEvent>,
  },
});

export type MdSliderProps = React.ComponentProps<typeof MdSlider>;
